param([string]$Output='docs/jv/fixtures/zigzag-geometry-excel.json')
$ErrorActionPreference='Stop'
$resolved=(& node tools/jv/resolve-excel-sources.mjs | ConvertFrom-Json)
$books=@(@{profile='COMPLETATION';path=$resolved.completion.path;hash=$resolved.completion.sha256},@{profile='RETAIL';path=$resolved.retail.path;hash=$resolved.retail.sha256})
$scenarios=@(@{id='zigzag_yes_3600x2400_4leaf';width=3600;height=2400;leaves=4;openingSelector=2;setting=1},@{id='zigzag_no_3600x2400_4leaf';width=3600;height=2400;leaves=4;openingSelector=2;setting=2},@{id='zigzag_yes_4200x2500_5leaf';width=4200;height=2500;leaves=5;openingSelector=3;setting=1},@{id='zigzag_no_4200x2500_5leaf';width=4200;height=2500;leaves=5;openingSelector=3;setting=2})
$xl=New-Object -ComObject Excel.Application;$xl.Visible=$false;$xl.DisplayAlerts=$false;$xl.AutomationSecurity=3;$xl.EnableEvents=$false
$results=[System.Collections.Generic.List[object]]::new()
try { foreach($b in $books){foreach($s in $scenarios){$tmp=Join-Path $env:TEMP ('jv-zigzag-'+[guid]::NewGuid().ToString('N')+'.xlsm');Copy-Item -LiteralPath $b.path -Destination $tmp
 $wb=$xl.Workbooks.Open($tmp);try{$m=$wb.Worksheets.Item('Главная');$st=$wb.Worksheets.Item('Настройки');$st.Range('H2').Value2=$s.setting;$m.Range('F11').Value2=2;$m.Range('C11').Value2=$s.width;$m.Range('D11').Value2=$s.height;$m.Range('L11').Value2=$s.leaves;$m.Range('J11').Value2=$s.openingSelector;$xl.CalculateFullRebuild();$z=$wb.Worksheets.Item('Z1');$look=$wb.Worksheets.Item('#1');$settings=@{};foreach($a in @('P4','P24','P25','P26','P27','P28','P29','L23','D8','P3')){$settings[$a]=[string]$st.Range($a).Value2};$cells=@{};foreach($a in @('D5','D6','H4','H5','H6','H7','H8','H9','H13','H14','H15','H16','H17','H18','D29','D30','D31','N5','N8','N9','N10','N11','N12','N13','N14','N29','N15','N16','N17','N18','N19','N27','N28','N32','N33')){$cells[$a]=[string]$z.Range($a).Value2};$results.Add(@{id=$s.id;profile=$b.profile;workbook=[IO.Path]::GetFileName($b.path);sha256=$b.hash;excelVersion=$xl.Version;inputs=@{family='ZIGZAG';selectorF=2;widthMm=$s.width;heightMm=$s.height;leafSelector=$s.leaves;openingSelector=$s.openingSelector;frameSettingIndex=$s.setting;frameOverrideIndex=[int]$z.Range('C13').Value2;frameChoices=@([string]$look.Range('F3').Value2,[string]$look.Range('F4').Value2);switches=@{D14=@{settingIndex=[int]$st.Range('H4').Value2;overrideIndex=[int]$z.Range('C14').Value2;choices=@([string]$look.Range('G3').Value2,[string]$look.Range('G4').Value2)};D15=@{settingIndex=[int]$st.Range('H6').Value2;overrideIndex=[int]$z.Range('C15').Value2;choices=@([string]$look.Range('F7').Value2,[string]$look.Range('F8').Value2)};D16=@{settingIndex=[int]$st.Range('H8').Value2;overrideIndex=[int]$z.Range('C16').Value2;choices=@([string]$look.Range('G7').Value2,[string]$look.Range('G8').Value2)};D17=@{settingIndex=[int]$st.Range('H10').Value2;overrideIndex=[int]$z.Range('C17').Value2;choices=@([string]$look.Range('F11').Value2,[string]$look.Range('F12').Value2)}}};settings=$settings;cells=$cells})}finally{$wb.Close($false);Remove-Item -LiteralPath $tmp -Force}}} } finally {$xl.Quit();[void][Runtime.InteropServices.Marshal]::ReleaseComObject($xl)}
$json=@{schemaVersion=1;method='Excel 16 COM CalculateFullRebuild on temporary copies; outputs captured after recompute; originals remain unchanged';cases=@($results)}|ConvertTo-Json -Depth 8
$out=Join-Path (Get-Location) $Output;[IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($out))|Out-Null;[IO.File]::WriteAllText($out,$json,[Text.UTF8Encoding]::new($false));Write-Output "Wrote $($results.Count) Zigzag Excel cases to $Output"
